{
  "status": "answered",
  "claims": [
    {
      "text": "يكون مدة الإجازة السنوية 21 يوماً بأجر كامل لمن أمضى في الخدمة سنة كاملة، تزاد إلى ثلاثين يوماً متى أمضى العامل في الخدمة عشر سنوات لدى صاحب عمل أو أكثر.",
      "source_ids": ["S1"]
    },
    {
      "text": "تزيد مدة الإجازة السنوية سبعة أيام للعمال الذين يعملون في الأعمال الشاقة أو الخطرة أو المضرة بالصحة أو في المناطق النائية.",
      "source_ids": ["S1"]
    },
    {
      "text": "تكون الإجازة لمدة ثلاثين يوماً في السنة لمن تجاوز سن الخمسين.",
      "source_ids": ["S1"]
    }
  ],
  "clarification_question": null
}

{
  "status": "answered",
